arguments.file_text:
@namespace Components

<div class="checkout-wizard">
    @switch (_currentStep)
    {
        case WizardStep.Shipping:
            <ShippingStep ShippingInfo="_order.Shipping"
                          OnNext="HandleShippingComplete" />
            break;

        case WizardStep.Payment:
            <PaymentStep PaymentInfo="_order.Payment"
                         OnBack="HandleBackToShipping"
                         OnPlaceOrder="HandlePlaceOrder" />
            break;
    }
</div>

@code {
    [Parameter]
    public EventCallback<Order> OnOrderPlaced { get; set; }

    private Order _order = new();
    private WizardStep _currentStep = WizardStep.Shipping;

    private void HandleShippingComplete()
    {
        _currentStep = WizardStep.Payment;
    }

    private void HandleBackToShipping()
    {
        _currentStep = WizardStep.Shipping;
    }

    private async Task HandlePlaceOrder()
    {
        await OnOrderPlaced.InvokeAsync(_order);
    }

    private enum WizardStep
    {
        Shipping,
        Payment
    }
}

@namespace Components
@inject IAddressValidator AddressValidator
@implements IDisposable

<div class="shipping-step">
    <h3>Shipping Information</h3>

    <div class="form-group">
        <label for="name">Name</label>
        <input id="name" @bind="ShippingInfo.Name" disabled="@_isValidating" />
    </div>

    <div class="form-group">
        <label for="address">Address</label>
        <input id="address" @bind="ShippingInfo.Address" disabled="@_isValidating" />
    </div>

    <div class="form-group">
        <label for="city">City</label>
        <input id="city" @bind="ShippingInfo.City" disabled="@_isValidating" />
    </div>

    <div class="form-group">
        <label for="zip">Zip Code</label>
        <input id="zip" @bind="ShippingInfo.ZipCode" disabled="@_isValidating" />
    </div>

    @if (!string.IsNullOrEmpty(_validationError))
    {
        <div class="validation-error">@_validationError</div>
    }

    <button @onclick="HandleNext" disabled="@_isValidating">
        @if (_isValidating)
        {
            <span class="spinner"></span>
            <span>Validating...</span>
        }
        else
        {
            <span>Next</span>
        }
    </button>
</div>

@code {
    [Parameter]
    public ShippingInfo ShippingInfo { get; set; } = default!;

    [Parameter]
    public EventCallback OnNext { get; set; }

    private bool _isValidating;
    private string? _validationError;
    private CancellationTokenSource? _cts;

    private async Task HandleNext()
    {
        _validationError = null;

        // Cancel any previous in-flight validation
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = new CancellationTokenSource();
        var token = _cts.Token;

        _isValidating = true;

        try
        {
            var isValid = await AddressValidator.ValidateAddressAsync(
                ShippingInfo.Address,
                ShippingInfo.City,
                ShippingInfo.ZipCode,
                token);

            token.ThrowIfCancellationRequested();

            if (isValid)
            {
                await OnNext.InvokeAsync();
            }
            else
            {
                _validationError = "The address could not be verified. Please check your details.";
            }
        }
        catch (OperationCanceledException)
        {
            // Validation was cancelled — no action needed
        }
        finally
        {
            _isValidating = false;
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

